INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10001, 1, "2023/06/30 12:00:00", 126401, "クローチェ", "いらっしゃいませっ♪\nキャラバンコインを使って\n買い物ができますよっ！", 2, 1, 0, "2023/09/22 14:59:59", 2002, 1.47, 1);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10002, 2, "2023/06/30 12:00:00", 126401, "クローチェ", "素敵な品が揃ってるので\nたーっくさん買っていって\nくださいねっ♪", 1, 2, 0, "2023/09/22 14:59:59", 2002, 2.15, 1);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10003, 1, "2023/06/30 12:00:00", 126501, "ライラエル", "ショップへようこそ\nキャラバンコインはこちら\nで買い物に使えますよ", 2, 2, 0, "2023/09/22 14:59:59", 2002, 0, 1);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10004, 2, "2023/06/30 12:00:00", 126501, "ライラエル", "こちらのショップで\n買い物をして、素敵な\n旅を楽しんでくださいね", 1, 1, 0, "2023/09/22 14:59:59", 2002, 0, 1);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10005, 1, "2023/09/15 15:00:00", 127702, "リンド", "いらっしゃいませ\nキャラバンコインを使って\nお買い物ができますよ", 2, 2, 0, "2023/12/22 14:59:59", 2002, 0, 2);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10006, 2, "2023/09/15 15:00:00", 127702, "リンド", "ショップの掃除は完璧です\n姫さま直営のお店として\n当然のことですから", 2, 2, 0, "2023/12/22 14:59:59", 2002, 0, 2);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10007, 1, "2023/09/15 15:00:00", 127802, "ヴルム", "ショップへようこそ\nキャラバンコインと品物を\n交換できるんで、よければ", 1, 1, 0, "2023/12/22 14:59:59", 2002, 0, 2);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10008, 2, "2023/09/15 15:00:00", 127802, "ヴルム", "なんで店番なんか…\nま、やりますけど\n好きな品物をどうぞ", 1, 2, 0, "2023/12/22 14:59:59", 2002, 6.5, 2);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10009, 1, "2023/12/15 15:00:00", 129602, "アネモネ", "──いらっしゃいませ\n買い物しても、いいですよ\nキャラバンコインがあれば", 1, 2, 0, "2024/03/22 14:59:59", 2002, 0, 3);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10010, 2, "2023/12/15 15:00:00", 129602, "アネモネ", "──もっと笑顔がほしい？\nいくらコインを積まれても\n売れない物はありますから", 1, 2, 0, "2024/03/22 14:59:59", 2002, 0, 3);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10011, 1, "2023/12/15 15:00:00", 129701, "ネフィ=ネラ", "ようこそおいでなんし\nキャラバンコインをこちら\nで交換して進ぜんしょう", 1, 1, 0, "2024/03/22 14:59:59", 2002, 0, 3);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10012, 2, "2023/12/15 15:00:00", 129701, "ネフィ=ネラ", "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", 1, 2, 0, "2024/03/22 14:59:59", 2002, 6.2, 3);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10013, 1, "2024/03/15 15:00:00", 130301, "カノン", "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", 5, 3, 0, "2024/06/22 14:59:59", 2002, 3.1, 4);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10014, 2, "2024/03/15 15:00:00", 130301, "カノン", "あら、あたくしをご所望？\nお生憎様、そんな小銭では\n…買えちゃうんですの！？", 2, 3, 0, "2024/06/22 14:59:59", 2002, 6.15, 4);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10015, 1, "2024/03/15 15:00:00", 130401, "ナーナ", "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", 2, 2, 0, "2024/06/22 14:59:59", 2002, 0, 4);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10016, 2, "2024/03/15 15:00:00", 130401, "ナーナ", "甘いのくれたら、\nお礼にナーナの拾った\n松ぼっくりあげちゃうよ！", 1, 2, 0, "2024/06/22 14:59:59", 2002, 3.35, 4);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10017, 1, "2024/06/15 15:00:00", 130502, "ホウオウ", "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", 1, 1, 0, "2024/09/22 14:59:59", 2002, 0, 5);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10018, 2, "2024/06/15 15:00:00", 130502, "ホウオウ", "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", 1, 2, 0, "2024/09/22 14:59:59", 2002, 3.18, 5);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10019, 3, "2024/06/15 15:00:00", 130503, "ホウオウ", "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", 4, 4, 0, "2024/09/22 14:59:59", 2002, 0, 5);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10020, 1, "2024/06/15 15:00:00", 123301, "ネア", "おっすー♪\nなんでも交換してけー\nカリザきゅん以外で", 2, 1, 0, "2024/09/22 14:59:59", 2002, 4.9, 5);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10021, 2, "2024/06/15 15:00:00", 123301, "ネア", "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", 2, 1, 0, "2024/09/22 14:59:59", 2002, 4.8, 5);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10022, 1, "2024/09/15 15:00:00", 133301, "カリザ", "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", 1, 3, 0, "2024/12/22 14:59:59", 2002, 4.922, 6);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10023, 2, "2024/09/15 15:00:00", 133301, "カリザ", "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", 5, 3, 0, "2024/12/22 14:59:59", 2002, 9.638, 6);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10024, 1, "2024/09/15 15:00:00", 133401, "ミーア", "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", 2, 1, 0, "2024/12/22 14:59:59", 2002, 2.88, 6);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10025, 2, "2024/09/15 15:00:00", 133401, "ミーア", "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", 1, 5, 0, "2024/12/22 14:59:59", 2002, 4.818, 6);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10026, 1, "2024/12/15 15:00:00", 133002, "グレイス", "へい、らっしゃい\nさ、騎士氏。冥土の土産は\nなにがいいですか？", 1, 2, 0, "2025/03/22 14:59:59", 2002, 1.78, 7);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10027, 2, "2024/12/15 15:00:00", 133002, "グレイス", "商品をお買い上げ毎に\nグレイスちゃんポイントを\n差し上げます。嘘ですが", 7, 1, 0, "2025/03/22 14:59:59", 2002, 6.15, 7);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10028, 1, "2024/12/15 15:00:00", 133102, "ヴァイオレット", "ようこそいらっしゃいませ\n…接客とは、このような\n振舞で宜しいでしょうか？", 2, 6, 0, "2025/03/22 14:59:59", 2002, 4.28, 7);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10029, 2, "2024/12/15 15:00:00", 133102, "ヴァイオレット", "じめじめした商品は\nございませんので\n安心してお買い求め下さい", 1, 1, 0, "2025/03/22 14:59:59", 2002, 0, 7);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10030, 1, "2025/03/15 15:00:00", 136902, "ルルィ", "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", 1, 2, 0, "2025/06/23 14:59:59", 2002, 5.53, 8);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10031, 2, "2025/03/15 15:00:00", 136902, "ルルィ", "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", 7, 9, 0, "2025/06/23 14:59:59", 2002, 6.05, 8);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10032, 1, "2025/03/15 15:00:00", 137001, "デュラン", "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", 1, 2, 0, "2025/06/23 14:59:59", 2002, 0, 8);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10033, 2, "2025/03/15 15:00:00", 137001, "デュラン", "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", 1, 2, 0, "2025/06/23 14:59:59", 2002, 0, 8);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10034, 1, "2025/06/16 15:00:00", 135902, "サツキ", "おう\n好きなもん持ってきな", 2, 2, 0, "2025/09/23 14:59:59", 2002, 0, 9);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10035, 2, "2025/06/16 15:00:00", 135902, "サツキ", "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", 6, 1, 0, "2025/09/23 14:59:59", 2002, 4.935, 9);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10036, 1, "2025/06/16 15:00:00", 135802, "ユキノ", "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", 5, 2, 0, "2025/09/23 14:59:59", 2002, 7.441, 9);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10037, 2, "2025/06/16 15:00:00", 135802, "ユキノ", "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", 7, 7, 0, "2025/09/23 14:59:59", 2002, 0, 9);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10038, 1, "2025/09/16 15:00:00", 130901, "クルル", "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", 2, 2, 0, "2025/12/22 14:59:59", 2002, 2.295, 10);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10039, 2, "2025/09/16 15:00:00", 130901, "クルル", "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", 6, 1, 0, "2025/12/22 14:59:59", 2002, 6.281, 10);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10040, 1, "2025/09/16 15:00:00", 137701, "ヴォルガーノ", "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", 1, 2, 0, "2025/12/22 14:59:59", 2002, 5.549, 10);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10041, 2, "2025/09/16 15:00:00", 137701, "ヴォルガーノ", "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", 6, 3, 0, "2025/12/22 14:59:59", 2002, 2.64, 10);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10042, 1, "2025/12/15 15:00:00", 132801, "ライラエル", "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", 4, 7, 0, "2026/03/23 11:59:59", 2002, 7.642, 11);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10043, 2, "2025/12/15 15:00:00", 132802, "ライラエル", "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", 1, 1, 0, "2026/03/23 11:59:59", 2002, 0, 11);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10044, 1, "2025/12/15 15:00:00", 134502, "クローチェ", "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", 1, 1, 0, "2026/03/23 11:59:59", 2002, 0, 11);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10045, 2, "2025/12/15 15:00:00", 134501, "クローチェ", "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", 1, 2, 0, "2026/03/23 11:59:59", 2002, 3.72, 11);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10046, 1, "2026/03/16 12:00:00", 138201, "ネフィ＝ネラ", "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", 1, 2, 0, "2026/06/22 11:59:59", 2002, 4.991, 12);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10047, 2, "2026/03/16 12:00:00", 138201, "ネフィ＝ネラ", "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", 4, 1, 0, "2026/06/22 11:59:59", 2002, 3.877, 12);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10048, 1, "2026/03/16 12:00:00", 136001, "アラクネ", "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", 6, 4, 0, "2026/06/22 11:59:59", 2002, 1.71, 12);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10049, 2, "2026/03/16 12:00:00", 136001, "アラクネ", "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", 2, 5, 0, "2026/06/22 11:59:59", 2002, 5.32, 12);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10050, 1, "2026/06/15 12:00:00", 135401, "アネモネ", "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", 4, 9, 0, "2026/09/22 11:59:59", 2002, 3.727, 13);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10051, 2, "2026/06/15 12:00:00", 135401, "アネモネ", "──リアみたいに、\nもっと愛想良い接客を…\nいえ──なんでもないです", 9, 7, 0, "2026/09/22 11:59:59", 2002, 7.213, 13);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10052, 1, "2026/06/15 12:00:00", 135301, "クリア", "いらっしゃいませー♪\n奉仕活動兼、将来のために\nたくさん働いちゃいます♪", 2, 1, 0, "2026/09/22 11:59:59", 2002, 1.874, 13);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10053, 2, "2026/06/15 12:00:00", 135301, "クリア", "アルバイトが終わったら\n海に遊びに行きましょう！\nモネちゃんも一緒に♪", 2, 2, 0, "2026/09/22 11:59:59", 2002, 0, 13);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10054, 1, "2026/09/15 12:00:00", 138001, "ヴァイオレット", "大いなる命、神なる勇魚…\n慈しみの矜持を胸に素敵な\n商品をお売りいたします", 1, 2, 0, "2026/12/22 11:59:59", 2002, 4.215, 14);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10055, 2, "2026/09/15 12:00:00", 138001, "ヴァイオレット", "すみません、わたくしの\n手料理は売り切れなのです\nグレイスが、買い占めを…", 4, 4, 0, "2026/12/22 11:59:59", 2002, 0, 14);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (-470, 10056, 1, "2026/09/15 12:00:00", 138901, "グレイス", "何故かいかがわしいお店と\n勘違いされるんですよね\n騎士氏も？　ヤダへんふし", 1, 6, 0, "2026/12/22 11:59:59", 2002, 5.477, 14);
